/* Stark Math. Physics generators: kinematics, forces, energy, momentum, waves, electricity,
   optics, thermodynamics, and introductory relativity and quantum physics. Answers are quantities with units:
   any equivalent unit is accepted (km/h for m/s, kJ for J, °C for K) and significant figures are checked sensibly.
   Constants come from data/constants.js (CODATA 2018). */
(function () {
  'use strict';
  const G = typeof window !== 'undefined' ? window : globalThis;
  const SM = G.SM, C = G.SM_DATA.C;
  const { A, Dim } = SM;
  const U = { v: Dim(1, 0, -1), a: Dim(1, 0, -2), F: Dim(1, 1, -2), E: Dim(2, 1, -2), P: Dim(2, 1, -3), p: Dim(1, 1, -1), m: Dim(0, 1), t: Dim(0, 0, 1), L: Dim(1), f: Dim(0, 0, -1), V: Dim(2, 1, -3, -1), I: Dim(0, 0, 0, 1), R: Dim(2, 1, -3, -2), Q: Dim(0, 0, 1, 1), T: Dim(0, 0, 0, 0, 1), Pa: Dim(-1, 1, -2), vol: Dim(3), k: Dim(0, 1, -2), none: Dim(), Cap: Dim(-2, -1, 4, 2) };
  SM.DIMS = U;
  const DEG = Math.PI / 180;
  const f = (x, sf) => SM.fmtSF(x, sf || 3);

  /** Physics skill factory. d.calc(p) returns the answer in SI; d.unit is the display unit. */
  function phys(d) {
    return { id: d.id, strand: d.strand, title: d.title, lv: d.lv, grade: d.grade, focus: d.focus, proof: d.proof, gen: d.gen,
      make(p, L) {
        const v = d.calc(p), sf = p.sf || 3, unit = typeof d.unit === 'function' ? d.unit(p, L) : d.unit, opt = L.lv === 0 || !!d.opt;
        const uf = SM.parseUnit(unit), show = x => SM.fmtSF(x / uf.f - (uf.temp && uf.off ? uf.off / uf.f : 0), sf) + (unit === '°' ? '°' : ' ' + unit);
        const c = { v, sf, unit, show, f: (x, s) => f(x, s || sf) };
        const ans = d.approx !== undefined ? A.approx(v, d.approx) : A.qty(v, d.dim === 'auto' ? uf.d : U[d.dim], sf, unit, { opt });
        return { q: d.q(p, L, c) + (d.approx !== undefined ? '' : opt ? ' Give your answer in ' + unit + '.' : ' Include the unit.'), ans,
          steps: d.steps(p, c, L), hints: d.hints(p, c, L), pic: d.pic ? d.pic(p) : null, proof: d.proof,
          mistakes: (d.mk ? d.mk(p, c, L) : []).filter(x => x && isFinite(x[0])).map(([w, id, msg]) => ({ spec: d.approx !== undefined ? A.approx(w, d.approx) : A.qty(w, d.dim === 'auto' ? uf.d : U[d.dim], sf, unit, { opt }), id, msg })) };
      } };
  }
  SM.phys = phys;

  SM.addSkills('physics', [
    /* ---------------- kinematics ---------------- */
    phys({ id: 'ph-speed', strand: 'Kinematics', title: 'Speed, distance and time', lv: [0, 2], grade: '5-8', focus: 'speed = distance ÷ time', dim: 'v',
      gen: (r, L) => L.kid ? (t => ({ d: r.int(4, 30) * t, t, sf: 2, kid: 1 }))(r.pick([2, 3, 4, 5])) : { d: r.sig(100, 5000, 3), t: r.sig(10, 600, 3), sf: 3 },
      calc: p => (p.kid ? p.d * 1000 / (p.t * 3600) : p.d / p.t), unit: p => (p.kid ? 'km/h' : 'm/s'),
      q: (p, L) => p.kid ? 'A train travels ' + p.d + ' km in ' + p.t + ' hours at a steady speed. How fast is it going?' : 'A cyclist covers ' + f(p.d) + ' m in ' + f(p.t) + ' s. What is the average speed?',
      steps: (p, c) => [{ t: 'Speed = distance ÷ time.' }, { t: (p.kid ? p.d + ' km ÷ ' + p.t + ' h' : f(p.d) + ' m ÷ ' + f(p.t) + ' s') + ' = ' + c.show(c.v) + '.' }],
      hints: (p, c) => ['Speed tells you how far you go each ' + (p.kid ? 'hour' : 'second') + '.', 'Divide the distance by the time.', p.kid ? p.d + ' ÷ ' + p.t + ' = ?' : f(p.d) + ' ÷ ' + f(p.t) + '.'],
      mk: (p, c) => [[p.kid ? p.t * 3600 / (p.d * 1000) * 1 : p.t / p.d, 'flip', 'That is time ÷ distance. Speed is distance ÷ time.'], [p.kid ? p.d * p.t * 1000 / 3600 : p.d * p.t, 'times', 'Multiplying gives the wrong kind of answer. Speed is distance divided by time.']],
      pic: p => (p.kid ? { type: 'road', d: p.d, t: p.t } : null) }),
    phys({ id: 'ph-v-uat', strand: 'Kinematics', title: 'Final velocity: v = u + at', lv: [1, 3], grade: '9-12', focus: 'v = u + at', dim: 'v',
      gen: (r, L) => ({ u: r.sig(1, 20, 3), a: r.sig(0.5, 9.5, 3) * (L.t > 0.5 && r.chance(0.3) ? -1 : 1), t: r.sig(1, 12, 3) }),
      calc: p => p.u + p.a * p.t, unit: 'm/s',
      q: p => 'A car moving at ' + f(p.u) + ' m/s ' + (p.a >= 0 ? 'accelerates at ' : 'slows with acceleration ') + f(p.a) + ' m/s² for ' + f(p.t) + ' s. What is its velocity at the end?',
      steps: (p, c) => [{ t: 'Use v = u + at.' }, { t: 'v = ' + f(p.u) + ' + (' + f(p.a) + ')(' + f(p.t) + ') = ' + c.show(c.v) + '.' }],
      hints: () => ['Which equation links u, a, t and v?', 'v = u + at.', 'Multiply a by t, then add the starting speed.'],
      mk: p => [[p.a * p.t, 'no-u', 'That leaves out the starting velocity u. The car was already moving.'], [p.u + p.a / p.t, 'divide', 'Acceleration is change in velocity per second, so multiply a by t.']] }),
    phys({ id: 'ph-s-ut', strand: 'Kinematics', title: 'Displacement: s = ut + ½at²', lv: [1, 3], grade: '10-12', focus: 'remembering the ½ and the square', dim: 'L',
      gen: r => ({ u: r.sig(1, 15, 3), a: r.sig(0.5, 6, 3), t: r.sig(2, 15, 3) }),
      calc: p => p.u * p.t + 0.5 * p.a * p.t * p.t, unit: 'm',
      q: p => 'An object starts at ' + f(p.u) + ' m/s and accelerates uniformly at ' + f(p.a) + ' m/s² for ' + f(p.t) + ' s. How far does it travel?',
      steps: (p, c) => [{ t: 's = ut + ½at².' }, { t: 's = (' + f(p.u) + ')(' + f(p.t) + ') + ½(' + f(p.a) + ')(' + f(p.t) + ')² = ' + c.show(c.v) + '.' }],
      hints: () => ['You know u, a and t. Which equation has no v?', 's = ut + ½at².', 'Square t before multiplying by ½a.'],
      mk: p => [[p.u * p.t + p.a * p.t * p.t, 'no-half', 'The acceleration term is ½at². The ½ is missing.'], [p.u * p.t + 0.5 * p.a * p.t, 'no-square', 'The acceleration term uses t², not t.']],
      proof: 'With constant a, v(t) = u + at. Displacement is the area under the v-t graph: a rectangle ut plus a triangle ½·t·at, so s = ut + ½at². Equivalently s = ∫₀ᵗ (u + aτ) dτ.' }),
    phys({ id: 'ph-v2', strand: 'Kinematics', title: 'v² = u² + 2as', lv: [1, 3], grade: '10-12', focus: 'the time-free equation', dim: 'v',
      gen: r => ({ u: r.sig(1, 12, 3), a: r.sig(1, 8, 3), s: r.sig(5, 200, 3) }),
      calc: p => Math.sqrt(p.u * p.u + 2 * p.a * p.s), unit: 'm/s',
      q: p => 'A sled starts at ' + f(p.u) + ' m/s and accelerates at ' + f(p.a) + ' m/s² over ' + f(p.s) + ' m. What is its final speed?',
      steps: (p, c) => [{ t: 'No time is given, so use v² = u² + 2as.' }, { t: 'v² = ' + f(p.u) + '² + 2(' + f(p.a) + ')(' + f(p.s) + ') = ' + f(c.v * c.v, 4) + ' m²/s².' }, { t: 'v = ' + c.show(c.v) + '.' }],
      hints: () => ['Which equation does not need the time?', 'v² = u² + 2as.', 'Remember to take the square root at the end.'],
      mk: p => [[p.u * p.u + 2 * p.a * p.s, 'no-root', 'That is v². Take the square root to get v.'], [p.u + Math.sqrt(2 * p.a * p.s), 'root-split', 'You cannot square-root the terms separately: v = √(u² + 2as).']],
      proof: 'Eliminate t from v = u + at and s = ut + ½at²: t = (v - u)/a, so s = u(v - u)/a + (v - u)²/2a = (v² - u²)/2a. Rearranged: v² = u² + 2as. It is also the work-energy theorem per unit mass: ½v² - ½u² = as.' }),
    phys({ id: 'ph-freefall', strand: 'Kinematics', title: 'Free fall', lv: [1, 3], grade: '9-12', focus: 'falling from rest with g', dim: 't',
      gen: r => ({ h: r.sig(2, 120, 3) }), calc: p => Math.sqrt(2 * p.h / 9.81), unit: 's',
      q: p => 'A stone is dropped from rest from a height of ' + f(p.h) + ' m. Ignoring air resistance and using g = 9.81 m/s², how long does it take to reach the ground?',
      steps: (p, c) => [{ t: 'From rest: h = ½gt², so t = √(2h/g).' }, { t: 't = √(2 × ' + f(p.h) + ' / 9.81) = ' + c.show(c.v) + '.' }],
      hints: () => ['It starts from rest, so u = 0.', 'h = ½gt². Rearrange for t.', 't = √(2h/g).'],
      mk: p => [[p.h / 9.81, 'linear', 'Falling objects speed up, so distance is not g × t. Use h = ½gt².'], [Math.sqrt(p.h / 9.81), 'no-2', 'Missing the factor 2: t = √(2h/g).']] }),
    phys({ id: 'ph-projectile', strand: 'Kinematics', title: 'Projectile range', lv: [2, 4], grade: '11-college', focus: 'treating horizontal and vertical motion separately', dim: 'L',
      gen: (r, L) => (L.t < 0.5 ? { v: r.sig(3, 25, 3), h: r.sig(1, 40, 3), mode: 0 } : { v: r.sig(8, 40, 3), th: r.int(15, 75), mode: 1 }),
      calc: p => (p.mode ? p.v * p.v * Math.sin(2 * p.th * DEG) / 9.81 : p.v * Math.sqrt(2 * p.h / 9.81)), unit: 'm',
      q: p => p.mode ? 'A ball is launched at ' + f(p.v) + ' m/s at ' + p.th + '° above level ground. Ignoring air resistance (g = 9.81 m/s²), how far away does it land?' : 'A ball rolls off a table ' + f(p.h) + ' m high at ' + f(p.v) + ' m/s horizontally. Ignoring air resistance (g = 9.81 m/s²), how far from the table does it land?',
      steps: (p, c) => p.mode ? [{ t: 'Time of flight T = 2v sinθ / g; range R = v cosθ × T = v² sin2θ / g.' }, { t: 'R = ' + f(p.v) + '² × sin(' + 2 * p.th + '°) / 9.81 = ' + c.show(c.v) + '.' }] : [{ t: 'Vertical: falls from rest, t = √(2h/g) = ' + f(Math.sqrt(2 * p.h / 9.81)) + ' s.' }, { t: 'Horizontal: constant speed, x = vt = ' + c.show(c.v) + '.' }],
      hints: p => ['Split the motion into horizontal and vertical parts.', p.mode ? 'Find the time in the air from the vertical motion.' : 'The fall time depends only on the height.', p.mode ? 'R = v² sin(2θ)/g.' : 't = √(2h/g), then x = vt.'],
      mk: p => p.mode ? [[p.v * p.v * Math.sin(p.th * DEG) / 9.81, 'sin-theta', 'The range uses sin(2θ), not sin θ.'], [p.v * p.v * Math.sin(2 * p.th) / 9.81, 'radians', 'Your calculator seems to be in radians.']] : [[p.v * 2 * p.h / 9.81, 'no-root', 'The fall time is √(2h/g); take the square root.']],
      proof: 'With x(t) = v cosθ t and y(t) = v sinθ t - ½gt², landing at y = 0 gives T = 2v sinθ/g, so R = v² · 2 sinθ cosθ / g = v² sin2θ / g, maximised at θ = 45°.' }),

    /* ---------------- forces ---------------- */
    phys({ id: 'ph-newton2', strand: 'Forces', title: 'Newton\'s second law', lv: [0, 3], grade: '6-12', focus: 'F = ma', dim: 'F',
      gen: (r, L) => (L.kid ? { m: r.int(2, 10), a: r.int(1, 5), sf: 2 } : { m: r.sig(0.5, 1500, 3), a: r.sig(0.2, 9, 3) }),
      calc: p => p.m * p.a, unit: 'N',
      q: (p, L) => L.kid ? 'You push a ' + p.m + ' kg cart so that it speeds up by ' + p.a + ' m/s every second. How big is the push (the force)?' : 'What net force gives a ' + f(p.m) + ' kg object an acceleration of ' + f(p.a) + ' m/s²?',
      steps: (p, c) => [{ t: 'Force = mass × acceleration (F = ma).' }, { t: 'F = ' + f(p.m) + ' kg × ' + f(p.a) + ' m/s² = ' + c.show(c.v) + '.' }],
      hints: () => ['Heavier things need a bigger push to speed up the same amount.', 'F = m × a.', 'Multiply the mass by the acceleration.'],
      mk: p => [[p.m / p.a, 'divide', 'Force is mass times acceleration, not mass divided by acceleration.'], [p.m * 9.81, 'weight', 'That is the weight. The question asks for the force causing this acceleration.']] }),
    phys({ id: 'ph-weight', strand: 'Forces', title: 'Weight and mass', lv: [0, 2], grade: '6-9', focus: 'W = mg', dim: 'F',
      gen: (r, L) => ({ m: L.kid ? r.int(2, 60) : r.sig(0.2, 120, 3), g: r.pick(L.kid ? [9.8] : [9.81, 1.62, 3.71]), sf: L.kid ? 2 : 3 }),
      calc: p => p.m * p.g, unit: 'N',
      q: p => 'What is the weight of a ' + (p.sf === 2 ? p.m : f(p.m)) + ' kg mass ' + { 9.8: 'on Earth (g = 9.8 m/s²)', 9.81: 'on Earth (g = 9.81 m/s²)', 1.62: 'on the Moon (g = 1.62 m/s²)', 3.71: 'on Mars (g = 3.71 m/s²)' }[p.g] + '?',
      steps: (p, c) => [{ t: 'Weight is the force of gravity: W = mg.' }, { t: 'W = ' + p.m + ' × ' + p.g + ' = ' + c.show(c.v) + '.' }],
      hints: () => ['Mass is in kilograms; weight is a force in newtons.', 'W = m × g.', 'Use the g given for this place.'],
      mk: p => [[p.m, 'mass', 'That is the mass. Weight is a force: multiply by g.'], [p.m / p.g, 'divide', 'Multiply by g; do not divide.']] }),
    phys({ id: 'ph-friction', strand: 'Forces', title: 'Friction and net force', lv: [1, 3], grade: '10-12', focus: 'friction = μN, then F_net = ma', dim: 'a',
      gen: r => { const m = r.sig(2, 40, 3), mu = r.pick([0.10, 0.15, 0.20, 0.25, 0.30, 0.35]); return { m, mu, F: SM.roundSF(mu * m * 9.81 * (1.3 + r.next()), 3) }; },
      calc: p => (p.F - p.mu * p.m * 9.81) / p.m, unit: 'm/s^2',
      q: p => { const F = p.F; return 'A ' + f(p.m) + ' kg crate is pulled across a floor by a horizontal force of ' + f(F) + ' N. The coefficient of kinetic friction is ' + p.mu.toFixed(2) + '. Using g = 9.81 m/s², find the acceleration.'; },
      steps: (p, c) => { const F = p.F, fr = p.mu * p.m * 9.81; return [{ t: 'Friction = μN = μmg = ' + p.mu.toFixed(2) + ' × ' + f(p.m) + ' × 9.81 = ' + f(fr) + ' N.' }, { t: 'Net force = ' + f(F) + ' - ' + f(fr) + ' = ' + f(F - fr) + ' N.' }, { t: 'a = F_net / m = ' + c.show(c.v) + '.' }]; },
      hints: () => ['Two horizontal forces act: the pull and friction.', 'Friction = μ × normal force = μmg.', 'a = (pull - friction) / m.'],
      mk: p => [[p.F / p.m, 'no-friction', 'Friction opposes the pull. Subtract it before dividing by the mass.']] }),
    phys({ id: 'ph-incline', strand: 'Forces', title: 'Inclined planes', lv: [2, 4], grade: '11-college', focus: 'resolving gravity along the slope', dim: 'a',
      gen: (r, L) => ({ th: r.int(10, 50), mu: L.t < 0.4 ? 0 : r.pick([0.05, 0.10, 0.15, 0.20]) }),
      calc: p => 9.81 * (Math.sin(p.th * DEG) - p.mu * Math.cos(p.th * DEG)), unit: 'm/s^2',
      q: p => 'A block slides down a ' + p.th + '° slope' + (p.mu ? ' with coefficient of kinetic friction ' + p.mu.toFixed(2) : ' with no friction') + '. Using g = 9.81 m/s², what is its acceleration down the slope?',
      steps: (p, c) => [{ t: 'Along the slope gravity gives g sinθ; friction opposes with μg cosθ.' }, { t: 'a = 9.81(sin ' + p.th + '° - ' + p.mu.toFixed(2) + ' cos ' + p.th + '°) = ' + c.show(c.v) + '.' }],
      hints: () => ['Resolve the weight into parts along and perpendicular to the slope.', 'Along the slope: mg sinθ. Normal force: mg cosθ.', 'a = g(sinθ - μ cosθ).'],
      mk: p => [[9.81 * (Math.cos(p.th * DEG) - p.mu * Math.sin(p.th * DEG)), 'sin-cos', 'Sine and cosine are swapped. The component along the slope is g sinθ.']],
      pic: p => ({ type: 'incline', th: p.th }) }),
    phys({ id: 'ph-hooke', strand: 'Forces', title: 'Springs and Hooke\'s law', lv: [1, 3], grade: '9-12', focus: 'F = kx', dim: 'L',
      gen: r => ({ k: r.sig(20, 800, 3), F: r.sig(2, 60, 3) }), calc: p => p.F / p.k, unit: 'cm',
      q: p => 'A spring has spring constant ' + f(p.k) + ' N/m. How far does it stretch under a force of ' + f(p.F) + ' N? Give the extension in cm.',
      steps: (p, c) => [{ t: 'Hooke\'s law: F = kx, so x = F/k.' }, { t: 'x = ' + f(p.F) + ' / ' + f(p.k) + ' = ' + f(c.v) + ' m = ' + c.show(c.v) + '.' }],
      hints: () => ['Hooke\'s law links force and extension.', 'x = F / k.', 'Convert metres to centimetres at the end.'],
      mk: p => [[p.F * p.k / 10000, 'times', 'Divide the force by k; do not multiply.']] }),
    phys({ id: 'ph-circular', strand: 'Forces', title: 'Circular motion', lv: [2, 4], grade: '11-college', focus: 'F = mv²/r', dim: 'F',
      gen: r => ({ m: r.sig(0.1, 1200, 3), v: r.sig(2, 30, 3), r: r.sig(0.5, 80, 3) }), calc: p => p.m * p.v * p.v / p.r, unit: 'N',
      q: p => 'A ' + f(p.m) + ' kg object moves in a circle of radius ' + f(p.r) + ' m at ' + f(p.v) + ' m/s. What centripetal force is needed?',
      steps: (p, c) => [{ t: 'F = mv²/r.' }, { t: 'F = ' + f(p.m) + ' × ' + f(p.v) + '² / ' + f(p.r) + ' = ' + c.show(c.v) + '.' }],
      hints: () => ['The force points towards the centre.', 'Centripetal acceleration is v²/r.', 'F = m v² / r.'],
      mk: p => [[p.m * p.v / p.r, 'no-square', 'The speed is squared: F = mv²/r.'], [p.m * p.v * p.v * p.r, 'times-r', 'Divide by the radius: a tighter circle needs more force.']],
      proof: 'For uniform circular motion r(t) = r(cos ωt, sin ωt). Differentiating twice gives a = -ω² r, of magnitude ω²r = v²/r, pointing to the centre. Newton\'s second law then gives F = mv²/r.' }),
    phys({ id: 'ph-gravity', strand: 'Forces', title: 'Newton\'s law of gravitation', lv: [2, 4], grade: '11-college', focus: 'the inverse-square law', dim: 'F',
      gen: r => ({ m1: r.sig(1, 9.9, 3) * 1e24, m2: r.sig(100, 9000, 3), r: r.sig(6.5, 40, 3) * 1e6 }),
      calc: p => C.G * p.m1 * p.m2 / (p.r * p.r), unit: 'N',
      q: p => 'A ' + f(p.m2) + ' kg satellite orbits a planet of mass ' + f(p.m1) + ' kg at a distance of ' + f(p.r) + ' m from its centre. Using G = 6.674 × 10⁻¹¹ N m²/kg², find the gravitational force on the satellite.',
      steps: (p, c) => [{ t: 'F = G m₁ m₂ / r².' }, { t: 'F = 6.674 × 10⁻¹¹ × ' + f(p.m1) + ' × ' + f(p.m2) + ' / (' + f(p.r) + ')² = ' + c.show(c.v) + '.' }],
      hints: () => ['Gravity weakens with the square of the distance.', 'F = G m₁ m₂ / r².', 'Square the distance before dividing.'],
      mk: p => [[C.G * p.m1 * p.m2 / p.r, 'not-squared', 'The distance must be squared: F = Gm₁m₂/r².']] }),

    /* ---------------- energy ---------------- */
    phys({ id: 'ph-ke', strand: 'Energy', title: 'Kinetic energy', lv: [1, 3], grade: '8-12', focus: 'KE = ½mv²', dim: 'E',
      gen: r => ({ m: r.sig(0.05, 2000, 3), v: r.sig(1, 40, 3) }), calc: p => 0.5 * p.m * p.v * p.v, unit: 'J',
      q: p => 'What is the kinetic energy of a ' + f(p.m) + ' kg object moving at ' + f(p.v) + ' m/s?',
      steps: (p, c) => [{ t: 'KE = ½mv².' }, { t: 'KE = ½ × ' + f(p.m) + ' × ' + f(p.v) + '² = ' + c.show(c.v) + '.' }],
      hints: () => ['Kinetic energy depends on mass and speed.', 'KE = ½ m v².', 'Square the speed first.'],
      mk: p => [[p.m * p.v * p.v, 'no-half', 'Remember the ½: KE = ½mv².'], [0.5 * p.m * p.v, 'no-square', 'The speed is squared.'], [0.5 * p.m * p.v * p.v * 1e3, 'g-kg', 'Check the mass is in kilograms.']] }),
    phys({ id: 'ph-gpe', strand: 'Energy', title: 'Gravitational potential energy', lv: [1, 3], grade: '8-12', focus: 'GPE = mgh', dim: 'E',
      gen: r => ({ m: r.sig(0.2, 900, 3), h: r.sig(0.5, 150, 3) }), calc: p => p.m * 9.81 * p.h, unit: 'J',
      q: p => 'How much gravitational potential energy does a ' + f(p.m) + ' kg mass gain when lifted ' + f(p.h) + ' m? Use g = 9.81 m/s².',
      steps: (p, c) => [{ t: 'ΔE = mgh.' }, { t: 'ΔE = ' + f(p.m) + ' × 9.81 × ' + f(p.h) + ' = ' + c.show(c.v) + '.' }],
      hints: () => ['Lifting against gravity stores energy.', 'GPE = m × g × h.', 'Multiply all three.'],
      mk: p => [[p.m * p.h, 'no-g', 'Multiply by g as well: GPE = mgh.']] }),
    phys({ id: 'ph-work', strand: 'Energy', title: 'Work done by a force', lv: [1, 3], grade: '9-12', focus: 'W = Fd cosθ', dim: 'E',
      gen: (r, L) => ({ F: r.sig(5, 500, 3), d: r.sig(1, 60, 3), th: L.t < 0.4 ? 0 : r.pick([20, 30, 35, 45, 60]) }),
      calc: p => p.F * p.d * Math.cos(p.th * DEG), unit: 'J',
      q: p => 'A force of ' + f(p.F) + ' N ' + (p.th ? 'at ' + p.th + '° to the direction of motion ' : '') + 'moves an object ' + f(p.d) + ' m' + (p.th ? '' : ' in the direction of the force') + '. How much work does the force do?',
      steps: (p, c) => [{ t: 'W = Fd cosθ' + (p.th ? '' : ', and θ = 0 so cosθ = 1') + '.' }, { t: 'W = ' + f(p.F) + ' × ' + f(p.d) + (p.th ? ' × cos ' + p.th + '°' : '') + ' = ' + c.show(c.v) + '.' }],
      hints: p => ['Work = force × distance moved in the direction of the force.', p.th ? 'Only the part of the force along the motion counts: F cosθ.' : 'Multiply force by distance.', 'W = F d cosθ.'],
      mk: p => p.th ? [[p.F * p.d, 'no-cos', 'Only the component of the force along the motion does work. Multiply by cos θ.'], [p.F * p.d * Math.sin(p.th * DEG), 'sin', 'Use cos θ for the component along the motion.']] : [[p.F / p.d, 'divide', 'Work is force times distance.']] }),
    phys({ id: 'ph-power', strand: 'Energy', title: 'Power', lv: [1, 3], grade: '8-12', focus: 'P = W/t', dim: 'P',
      gen: r => ({ W: r.sig(200, 90000, 3), t: r.sig(2, 300, 3) }), calc: p => p.W / p.t, unit: 'W',
      q: p => 'A motor does ' + f(p.W) + ' J of work in ' + f(p.t) + ' s. What is its average power output?',
      steps: (p, c) => [{ t: 'Power = energy ÷ time.' }, { t: 'P = ' + f(p.W) + ' / ' + f(p.t) + ' = ' + c.show(c.v) + '.' }],
      hints: () => ['Power is how fast energy is transferred.', 'P = W / t.', 'Divide the work by the time.'],
      mk: p => [[p.W * p.t, 'times', 'Power is work divided by time.'], [p.t / p.W, 'flip', 'That is time ÷ work. Power = work ÷ time.']] }),
    phys({ id: 'ph-energy-cons', strand: 'Energy', title: 'Conservation of energy', lv: [1, 3], grade: '9-12', focus: 'mgh = ½mv²', dim: 'v',
      gen: r => ({ h: r.sig(0.5, 80, 3), m: r.sig(0.5, 80, 3) }), calc: p => Math.sqrt(2 * 9.81 * p.h), unit: 'm/s',
      q: p => 'A ' + f(p.m) + ' kg ball is released from rest and falls ' + f(p.h) + ' m. Ignoring air resistance (g = 9.81 m/s²), how fast is it moving at the bottom?',
      steps: (p, c) => [{ t: 'Energy lost as GPE becomes KE: mgh = ½mv². The mass cancels.' }, { t: 'v = √(2gh) = √(2 × 9.81 × ' + f(p.h) + ') = ' + c.show(c.v) + '.' }],
      hints: () => ['Where does the potential energy go?', 'mgh = ½mv². Does the mass matter?', 'v = √(2gh).'],
      mk: p => [[2 * 9.81 * p.h, 'no-root', 'That is v². Take the square root.'], [Math.sqrt(9.81 * p.h), 'no-2', 'From mgh = ½mv² you get v² = 2gh.']] }),
    phys({ id: 'ph-efficiency', strand: 'Energy', title: 'Efficiency', lv: [1, 2], grade: '8-10', focus: 'useful output ÷ total input', approx: 1,
      gen: r => ({ inp: r.int(20, 400) * 10, eff: r.int(15, 95) }), calc: p => p.eff * 1, unit: '%',
      q: p => 'A machine takes in ' + p.inp + ' J and delivers ' + (p.inp * p.eff / 100) + ' J of useful energy. What is its efficiency, in percent (to 1 decimal place)?',
      steps: (p, c) => [{ t: 'Efficiency = useful output ÷ total input × 100%.' }, { t: (p.inp * p.eff / 100) + ' / ' + p.inp + ' × 100 = ' + c.v.toFixed(1) + '%.' }],
      hints: () => ['What fraction of the energy is useful?', 'Divide useful output by input.', 'Multiply by 100 for a percentage.'],
      mk: p => [[p.eff / 100, 'no-100', 'Multiply the fraction by 100 to get a percentage.'], [100 * 100 / p.eff, 'flip', 'Divide useful output by input, not the other way round.']] }),

    /* ---------------- momentum ---------------- */
    phys({ id: 'ph-momentum', strand: 'Momentum', title: 'Momentum', lv: [1, 3], grade: '9-12', focus: 'p = mv', dim: 'p',
      gen: r => ({ m: r.sig(0.05, 2000, 3), v: r.sig(0.5, 40, 3) }), calc: p => p.m * p.v, unit: 'kg m/s',
      q: p => 'What is the momentum of a ' + f(p.m) + ' kg object moving at ' + f(p.v) + ' m/s?',
      steps: (p, c) => [{ t: 'p = mv.' }, { t: 'p = ' + f(p.m) + ' × ' + f(p.v) + ' = ' + c.show(c.v) + '.' }],
      hints: () => ['Momentum is "mass in motion".', 'p = m × v.', 'Units: kg m/s (the same as N s).'], mk: p => [[0.5 * p.m * p.v * p.v, 'ke', 'That is kinetic energy. Momentum is p = mv.']] }),
    phys({ id: 'ph-impulse', strand: 'Momentum', title: 'Impulse and force', lv: [1, 3], grade: '10-12', focus: 'F = Δp / Δt', dim: 'F',
      gen: r => ({ m: r.sig(0.05, 1.5, 3), dv: r.sig(5, 60, 3), t: r.sig(0.002, 0.2, 3) }), calc: p => p.m * p.dv / p.t, unit: 'N',
      q: p => 'A ' + f(p.m) + ' kg ball changes velocity by ' + f(p.dv) + ' m/s during a ' + f(p.t) + ' s contact with a bat. What average force acts on it?',
      steps: (p, c) => [{ t: 'Impulse = change in momentum: FΔt = mΔv.' }, { t: 'F = ' + f(p.m) + ' × ' + f(p.dv) + ' / ' + f(p.t) + ' = ' + c.show(c.v) + '.' }],
      hints: () => ['Force × time = change in momentum.', 'Find mΔv first.', 'Then divide by the contact time.'], mk: p => [[p.m * p.dv * p.t, 'times-t', 'Divide by the contact time; a shorter contact means a larger force.']] }),
    phys({ id: 'ph-collision', strand: 'Momentum', title: 'Perfectly inelastic collisions', lv: [1, 4], grade: '10-college', focus: 'total momentum before = total momentum after', dim: 'v',
      gen: (r, L) => ({ m1: r.sig(0.5, 2000, 3), u1: r.sig(1, 30, 3), m2: r.sig(0.5, 2000, 3), u2: L.t < 0.4 ? 0 : -r.sig(1, 20, 3) }),
      calc: p => (p.m1 * p.u1 + p.m2 * p.u2) / (p.m1 + p.m2), unit: 'm/s',
      q: p => 'A ' + f(p.m1) + ' kg cart moving at ' + f(p.u1) + ' m/s ' + (p.u2 ? 'meets a ' + f(p.m2) + ' kg cart moving at ' + f(-p.u2) + ' m/s in the opposite direction' : 'hits a stationary ' + f(p.m2) + ' kg cart') + '. They stick together. What is their velocity just after (positive = the first cart\'s direction)?',
      steps: (p, c) => [{ t: 'Momentum is conserved: m₁u₁ + m₂u₂ = (m₁ + m₂)v.' }, { t: 'v = (' + f(p.m1) + ' × ' + f(p.u1) + (p.u2 ? ' + ' + f(p.m2) + ' × (' + f(p.u2) + ')' : '') + ') / (' + f(p.m1) + ' + ' + f(p.m2) + ') = ' + c.show(c.v) + '.' }],
      hints: p => ['What is conserved in every collision?', 'Total momentum before = total momentum after.', p.u2 ? 'Give the second cart a negative velocity.' : 'The second cart starts with zero momentum.'],
      mk: p => [[(p.m1 * p.u1 - p.m2 * p.u2) / (p.m1 + p.m2), 'direction', 'Velocities in opposite directions have opposite signs.'], [p.m1 * p.u1 / p.m2, 'mass-only', 'After sticking together, the combined mass m₁ + m₂ moves.']].filter(x => Math.abs(x[0] - (p.m1 * p.u1 + p.m2 * p.u2) / (p.m1 + p.m2)) > 1e-9) }),
    phys({ id: 'ph-elastic', strand: 'Momentum', title: 'Elastic collisions', lv: [3, 4], grade: 'college', focus: 'conserving momentum and kinetic energy', dim: 'v',
      gen: r => ({ m1: r.sig(0.5, 10, 3), m2: r.sig(0.5, 10, 3), u1: r.sig(1, 20, 3) }), calc: p => (p.m1 - p.m2) / (p.m1 + p.m2) * p.u1, unit: 'm/s',
      q: p => 'A ' + f(p.m1) + ' kg ball at ' + f(p.u1) + ' m/s collides head-on and elastically with a stationary ' + f(p.m2) + ' kg ball. What is the first ball\'s velocity afterwards (positive = original direction)?',
      steps: (p, c) => [{ t: 'Solving momentum and kinetic-energy conservation together gives v₁ = (m₁ - m₂)/(m₁ + m₂) u₁.' }, { t: 'v₁ = (' + f(p.m1) + ' - ' + f(p.m2) + ')/(' + f(p.m1) + ' + ' + f(p.m2) + ') × ' + f(p.u1) + ' = ' + c.show(c.v) + '.' }],
      hints: () => ['Two quantities are conserved in an elastic collision.', 'Momentum and kinetic energy.', 'v₁ = (m₁ - m₂)u₁/(m₁ + m₂).'],
      mk: p => [[(p.m2 - p.m1) / (p.m1 + p.m2) * p.u1, 'sign', 'The sign is reversed: v₁ = (m₁ - m₂)u₁/(m₁ + m₂).'], [p.m1 * p.u1 / (p.m1 + p.m2), 'inelastic', 'That is the stick-together (inelastic) result.']],
      proof: 'Momentum: m₁(u₁ - v₁) = m₂v₂. Energy: m₁(u₁² - v₁²) = m₂v₂². Dividing, u₁ + v₁ = v₂ (relative speed reverses). Substituting back: v₁ = (m₁ - m₂)u₁/(m₁ + m₂), v₂ = 2m₁u₁/(m₁ + m₂).' }),

    /* ---------------- waves ---------------- */
    phys({ id: 'ph-wave', strand: 'Waves', title: 'The wave equation', lv: [1, 3], grade: '8-12', focus: 'v = fλ', dim: 'L',
      gen: r => ({ v: r.pick([343, 1480, 3.00e8]), f: r.sig(20, 9000, 3) }), calc: p => p.v / (p.v > 1e6 ? p.f * 1e11 : p.f), unit: 'm',
      q: p => p.v > 1e6 ? 'Electromagnetic waves travel at 3.00 × 10⁸ m/s. What is the wavelength of a wave with frequency ' + f(p.f * 1e11) + ' Hz?' : (p.v === 343 ? 'Sound travels at 343 m/s in air.' : 'Sound travels at 1480 m/s in water.') + ' What is the wavelength of a ' + f(p.f) + ' Hz tone?',
      steps: (p, c) => [{ t: 'v = fλ, so λ = v/f.' }, { t: 'λ = ' + (p.v > 1e6 ? '3.00 × 10⁸' : p.v) + ' / ' + f(p.v > 1e6 ? p.f * 1e11 : p.f) + ' = ' + c.show(c.v) + '.' }],
      hints: () => ['Speed, frequency and wavelength are linked.', 'v = f λ.', 'λ = v / f.'], mk: p => [[(p.v > 1e6 ? p.f * 1e11 : p.f) / p.v, 'flip', 'λ = v/f, not f/v.']] }),
    phys({ id: 'ph-period', strand: 'Waves', title: 'Period and frequency', lv: [1, 2], grade: '8-10', focus: 'T = 1/f', dim: 't',
      gen: r => ({ f: r.sig(2, 900, 3) }), calc: p => 1 / p.f, unit: 'ms',
      q: p => 'A wave has frequency ' + f(p.f) + ' Hz. What is its period, in milliseconds?',
      steps: (p, c) => [{ t: 'T = 1/f.' }, { t: 'T = 1/' + f(p.f) + ' = ' + f(c.v) + ' s = ' + c.show(c.v) + '.' }],
      hints: () => ['Period is the time for one cycle.', 'T = 1 / f.', '1 s = 1000 ms.'], mk: p => [[p.f / 1000, 'times', 'Period is one divided by the frequency.']] }),
    phys({ id: 'ph-echo', strand: 'Waves', title: 'Echoes', lv: [1, 2], grade: '8-10', focus: 'the sound goes there and back', dim: 'L',
      gen: r => ({ t: r.sig(0.2, 6, 3) }), calc: p => 343 * p.t / 2, unit: 'm',
      q: p => 'You shout towards a cliff and hear the echo ' + f(p.t) + ' s later. Sound travels at 343 m/s. How far away is the cliff?',
      steps: (p, c) => [{ t: 'The sound travels to the cliff and back: total distance = 343 × ' + f(p.t) + ' = ' + f(343 * p.t) + ' m.' }, { t: 'Half of that is the distance to the cliff: ' + c.show(c.v) + '.' }],
      hints: () => ['Where does the sound go?', 'It travels there and back.', 'Halve the total distance.'], mk: p => [[343 * p.t, 'no-half', 'The sound went to the cliff and back. Halve the distance.']] }),
    phys({ id: 'ph-doppler', strand: 'Waves', title: 'The Doppler effect', lv: [3, 4], grade: 'college', focus: 'f\' = f v / (v - vs)', dim: 'f',
      gen: r => ({ f: r.sig(200, 1200, 3), vs: r.sig(5, 60, 3), app: r.chance(0.5) ? 1 : 0 }), calc: p => p.f * 343 / (343 - (p.app ? p.vs : -p.vs)), unit: 'Hz',
      q: p => 'An ambulance siren emits ' + f(p.f) + ' Hz and moves at ' + f(p.vs) + ' m/s ' + (p.app ? 'towards' : 'away from') + ' a stationary listener. Sound travels at 343 m/s. What frequency is heard?',
      steps: (p, c) => [{ t: 'Moving source: f\' = f v / (v ∓ v_s), minus when approaching.' }, { t: 'f\' = ' + f(p.f) + ' × 343 / (343 ' + (p.app ? '-' : '+') + ' ' + f(p.vs) + ') = ' + c.show(c.v) + '.' }],
      hints: p => ['Does the pitch go up or down?', p.app ? 'Approaching: waves are squashed, so higher.' : 'Receding: waves are stretched, so lower.', 'f\' = f v / (v ' + (p.app ? '-' : '+') + ' v_s).'],
      mk: p => [[p.f * 343 / (343 + (p.app ? p.vs : -p.vs)), 'sign', 'The sign is the wrong way round: an approaching source sounds higher.']] }),
    phys({ id: 'ph-harmonic', strand: 'Waves', title: 'Standing waves on a string', lv: [2, 4], grade: '11-college', focus: 'fₙ = nv / 2L', dim: 'f',
      gen: r => ({ n: r.int(1, 4), v: r.sig(80, 400, 3), L: r.sig(0.3, 1.2, 3) }), calc: p => p.n * p.v / (2 * p.L), unit: 'Hz',
      q: p => 'Waves travel at ' + f(p.v) + ' m/s on a ' + f(p.L) + ' m string fixed at both ends. What is the frequency of the ' + ['', 'first (fundamental)', 'second', 'third', 'fourth'][p.n] + ' harmonic?',
      steps: (p, c) => [{ t: 'The nth harmonic fits n half-wavelengths: λ = 2L/n, so f = nv/(2L).' }, { t: 'f = ' + p.n + ' × ' + f(p.v) + ' / (2 × ' + f(p.L) + ') = ' + c.show(c.v) + '.' }],
      hints: () => ['How many half-wavelengths fit on the string?', 'λₙ = 2L / n.', 'f = v / λ.'], mk: p => [[p.n * p.v / p.L, 'no-2', 'The fundamental wavelength is 2L, not L.']] }),

    /* ---------------- electricity ---------------- */
    phys({ id: 'ph-ohm', strand: 'Electricity & circuits', title: 'Ohm\'s law', lv: [1, 3], grade: '8-12', focus: 'V = IR', dim: 'I',
      gen: r => ({ V: r.sig(1.5, 240, 3), R: r.sig(10, 4700, 3) }), calc: p => p.V / p.R, unit: 'mA',
      q: p => 'A ' + f(p.V) + ' V supply is connected across a ' + f(p.R) + ' Ω resistor. What current flows, in mA?',
      steps: (p, c) => [{ t: 'V = IR, so I = V/R.' }, { t: 'I = ' + f(p.V) + ' / ' + f(p.R) + ' = ' + f(c.v) + ' A = ' + c.show(c.v) + '.' }],
      hints: () => ['Ohm\'s law links voltage, current and resistance.', 'I = V / R.', '1 A = 1000 mA.'],
      mk: p => [[p.V * p.R / 1e6, 'times', 'Current is voltage divided by resistance.'], [p.R / p.V / 1000, 'flip', 'I = V/R, not R/V.']] }),
    phys({ id: 'ph-resistors', strand: 'Electricity & circuits', title: 'Series and parallel resistors', lv: [1, 3], grade: '9-12', focus: 'adding resistances or their reciprocals', dim: 'R',
      gen: r => ({ r1: r.pick([10, 22, 33, 47, 68, 100, 150, 220, 330, 470]), r2: r.pick([10, 22, 33, 47, 68, 100, 150, 220, 330, 470]), par: r.chance(0.6) ? 1 : 0 }),
      calc: p => (p.par ? p.r1 * p.r2 / (p.r1 + p.r2) : p.r1 + p.r2), unit: 'Ω',
      q: p => 'Resistors of ' + p.r1 + ' Ω and ' + p.r2 + ' Ω are connected in ' + (p.par ? 'parallel' : 'series') + '. What is the total resistance?',
      steps: (p, c) => p.par ? [{ t: 'Parallel: 1/R = 1/R₁ + 1/R₂, or R = R₁R₂/(R₁ + R₂).' }, { t: 'R = ' + p.r1 + ' × ' + p.r2 + ' / (' + p.r1 + ' + ' + p.r2 + ') = ' + c.show(c.v) + '.' }] : [{ t: 'Series resistances add: R = R₁ + R₂ = ' + c.show(c.v) + '.' }],
      hints: p => [p.par ? 'In parallel, the current has two paths.' : 'In series, the current goes through both.', p.par ? 'The total is less than the smallest resistor.' : 'Add them.', p.par ? 'R = R₁R₂/(R₁ + R₂).' : 'R = R₁ + R₂.'],
      mk: p => p.par ? [[p.r1 + p.r2, 'series', 'That is the series formula. In parallel, the total is smaller than either resistor.'], [1 / p.r1 + 1 / p.r2, 'no-flip', 'That is 1/R. Flip it to get R.']] : [[p.r1 * p.r2 / (p.r1 + p.r2), 'parallel', 'That is the parallel formula. In series, resistances simply add.']],
      pic: p => ({ type: 'circuit', par: p.par, r1: p.r1, r2: p.r2 }) }),
    phys({ id: 'ph-epower', strand: 'Electricity & circuits', title: 'Electrical power', lv: [1, 3], grade: '9-12', focus: 'P = VI = I²R = V²/R', dim: 'P',
      gen: r => { const V = r.sig(3, 240, 3), I = r.sig(0.1, 12, 3); return { V, I, R: SM.roundSF(V / I, 3), mode: r.int(0, 1) }; }, calc: p => (p.mode ? p.I * p.I * p.R : p.V * p.I), unit: 'W',
      q: p => p.mode ? 'A current of ' + f(p.I) + ' A flows through a ' + f(p.R) + ' Ω heater. What power does it dissipate?' : 'A device draws ' + f(p.I) + ' A from a ' + f(p.V) + ' V supply. What is its power?',
      steps: (p, c) => p.mode ? [{ t: 'P = I²R.' }, { t: 'P = ' + f(p.I) + '² × ' + f(p.R) + ' = ' + c.show(c.v) + '.' }] : [{ t: 'P = VI.' }, { t: 'P = ' + f(p.V) + ' × ' + f(p.I) + ' = ' + c.show(c.v) + '.' }],
      hints: p => ['Which two quantities do you know?', p.mode ? 'Current and resistance: P = I²R.' : 'Voltage and current: P = VI.', 'Multiply.'], mk: p => p.mode ? [[p.I * p.R, 'no-square', 'P = I²R: square the current.']] : [[p.V / p.I, 'divide', 'That is the resistance. Power = V × I.']] }),
    phys({ id: 'ph-charge', strand: 'Electricity & circuits', title: 'Charge and current', lv: [1, 3], grade: '9-12', focus: 'Q = It', dim: 'Q',
      gen: r => ({ I: r.sig(0.02, 5, 3), t: r.sig(5, 3600, 3) }), calc: p => p.I * p.t, unit: 'C',
      q: p => 'A current of ' + f(p.I) + ' A flows for ' + f(p.t) + ' s. How much charge passes?',
      steps: (p, c) => [{ t: 'Q = It.' }, { t: 'Q = ' + f(p.I) + ' × ' + f(p.t) + ' = ' + c.show(c.v) + '.' }], hints: () => ['Current is charge per second.', 'Q = I × t.', 'Multiply.'], mk: p => [[p.I / p.t, 'divide', 'Charge = current × time.']] }),
    phys({ id: 'ph-cost', strand: 'Electricity & circuits', title: 'Energy cost in kWh', lv: [2, 2], grade: 'adult', focus: 'kW × hours × price', approx: 2,
      gen: r => ({ P: r.pick([60, 100, 800, 1200, 1500, 2000, 2400, 3000]), h: r.int(1, 12), days: r.pick([1, 7, 30]), price: r.int(12, 45) }), calc: p => p.P / 1000 * p.h * p.days * p.price / 100, unit: '$',
      q: p => 'A ' + p.P + ' W appliance runs ' + p.h + ' hours a day for ' + p.days + ' day' + (p.days > 1 ? 's' : '') + '. Electricity costs ' + p.price + ' cents per kWh. What does it cost, in dollars, to the nearest cent?',
      steps: (p, c) => [{ t: 'Energy = ' + p.P / 1000 + ' kW × ' + p.h * p.days + ' h = ' + SM.fmtNum(p.P / 1000 * p.h * p.days) + ' kWh.' }, { t: 'Cost = ' + SM.fmtNum(p.P / 1000 * p.h * p.days) + ' × $' + (p.price / 100).toFixed(2) + ' = $' + c.v.toFixed(2) + '.' }],
      hints: () => ['Bills charge per kilowatt-hour.', 'Convert watts to kilowatts, then multiply by hours.', 'Multiply the kWh by the price.'], mk: p => [[p.P * p.h * p.days * p.price / 100, 'watts', 'Convert watts to kilowatts first (divide by 1000).'], [p.P / 1000 * p.h * p.days * p.price, 'cents', 'That is in cents. Divide by 100 for dollars.']] }),
    phys({ id: 'ph-coulomb', strand: 'Electricity & circuits', title: 'Coulomb\'s law', lv: [2, 4], grade: '11-college', focus: 'F = kq₁q₂/r²', dim: 'F',
      gen: r => ({ q1: r.sig(1, 9, 3) * 1e-6, q2: r.sig(1, 9, 3) * 1e-6, r: r.sig(0.02, 0.9, 3) }), calc: p => C.ke * p.q1 * p.q2 / (p.r * p.r), unit: 'N',
      q: p => 'Two charges of ' + f(p.q1 * 1e6) + ' μC and ' + f(p.q2 * 1e6) + ' μC are ' + f(p.r) + ' m apart. Using k = 8.99 × 10⁹ N m²/C², what is the size of the force between them?',
      steps: (p, c) => [{ t: 'F = k q₁ q₂ / r². Convert μC to C first (× 10⁻⁶).' }, { t: 'F = 8.99 × 10⁹ × ' + f(p.q1) + ' × ' + f(p.q2) + ' / ' + f(p.r) + '² = ' + c.show(c.v) + '.' }],
      hints: () => ['Like gravity, an inverse-square law.', 'Convert microcoulombs to coulombs.', 'F = k q₁ q₂ / r².'], mk: p => [[C.ke * p.q1 * p.q2 / p.r, 'not-squared', 'Square the distance.'], [C.ke * p.q1 * p.q2 * 1e12 / (p.r * p.r), 'micro', 'Convert μC to C (× 10⁻⁶) before using the formula.']] }),
    phys({ id: 'ph-capacitor', strand: 'Electricity & circuits', title: 'Energy in a capacitor', lv: [3, 4], grade: 'college', focus: 'E = ½CV²', dim: 'E',
      gen: r => ({ C: r.sig(1, 900, 3) * 1e-6, V: r.sig(5, 400, 3) }), calc: p => 0.5 * p.C * p.V * p.V, unit: 'J',
      q: p => 'A ' + f(p.C * 1e6) + ' μF capacitor is charged to ' + f(p.V) + ' V. How much energy does it store?',
      steps: (p, c) => [{ t: 'E = ½CV².' }, { t: 'E = ½ × ' + f(p.C) + ' × ' + f(p.V) + '² = ' + c.show(c.v) + '.' }], hints: () => ['Energy grows with the square of the voltage.', 'E = ½ C V².', 'Convert μF to F.'], mk: p => [[p.C * p.V * p.V, 'no-half', 'E = ½CV²: the ½ is missing.'], [0.5 * p.C * p.V, 'no-square', 'Square the voltage.']],
      proof: 'Moving charge dq onto a capacitor at voltage q/C costs (q/C) dq. Integrating from 0 to Q: E = Q²/2C = ½CV².' }),

    /* ---------------- optics ---------------- */
    phys({ id: 'ph-snell', strand: 'Optics', title: 'Refraction (Snell\'s law)', lv: [2, 4], grade: '11-college', focus: 'n₁ sinθ₁ = n₂ sinθ₂', approx: 1,
      gen: r => ({ n1: 1.00, n2: r.pick([1.33, 1.50, 1.52, 2.42]), th: r.int(10, 75) }), calc: p => Math.asin(p.n1 * Math.sin(p.th * DEG) / p.n2) / DEG, unit: '°',
      q: p => 'Light passes from air (n = 1.00) into a material with n = ' + p.n2.toFixed(2) + ' at ' + p.th + '° to the normal. What is the angle of refraction, in degrees to 1 decimal place?',
      steps: (p, c) => [{ t: 'sin θ₂ = n₁ sin θ₁ / n₂ = sin ' + p.th + '° / ' + p.n2.toFixed(2) + ' = ' + f(Math.sin(p.th * DEG) / p.n2, 4) + '.' }, { t: 'θ₂ = sin⁻¹(' + f(Math.sin(p.th * DEG) / p.n2, 4) + ') = ' + c.v.toFixed(1) + '°.' }],
      hints: () => ['Light bends towards the normal entering a denser material.', 'n₁ sin θ₁ = n₂ sin θ₂.', 'Use inverse sine at the end.'], mk: p => [[p.th / p.n2, 'angles', 'Snell\'s law uses the sines of the angles, not the angles themselves.']] }),
    phys({ id: 'ph-lens', strand: 'Optics', title: 'Thin lenses', lv: [2, 4], grade: '11-college', focus: '1/f = 1/u + 1/v', dim: 'L',
      gen: r => { const fl = r.sig(5, 30, 3); return { f: fl, u: SM.roundSF(fl * (1.3 + r.next() * 2.5), 3) }; }, calc: p => 1 / (1 / p.f - 1 / p.u), unit: 'cm',
      q: p => 'An object is ' + f(p.u * 100) + ' cm from a converging lens of focal length ' + f(p.f * 100) + ' cm. Where does the image form (distance from the lens, in cm)?',
      steps: (p, c) => [{ t: '1/v = 1/f - 1/u (real-is-positive convention).' }, { t: '1/v = 1/' + f(p.f * 100) + ' - 1/' + f(p.u * 100) + ', so v = ' + c.show(c.v) + '.' }],
      hints: () => ['Use the thin lens equation.', '1/f = 1/u + 1/v.', 'Rearrange for v and take the reciprocal at the end.'], mk: p => [[1 / (1 / p.f + 1 / p.u), 'plus', 'Subtract: 1/v = 1/f - 1/u.'], [1 / p.f - 1 / p.u, 'no-flip', 'That is 1/v. Take the reciprocal.']] }),
    phys({ id: 'ph-critical', strand: 'Optics', title: 'Critical angle', lv: [2, 4], grade: '11-college', focus: 'sin c = n₂/n₁', approx: 1,
      gen: r => ({ n1: r.pick([1.33, 1.50, 1.52, 1.65, 2.42]) }), calc: p => Math.asin(1 / p.n1) / DEG, unit: '°',
      q: p => 'What is the critical angle for light going from a material with n = ' + p.n1.toFixed(2) + ' into air (n = 1.00), in degrees to 1 decimal place?',
      steps: (p, c) => [{ t: 'At the critical angle the refracted ray grazes the surface (θ₂ = 90°): sin c = n₂/n₁.' }, { t: 'c = sin⁻¹(1.00/' + p.n1.toFixed(2) + ') = ' + c.v.toFixed(1) + '°.' }],
      hints: () => ['What is the refraction angle at the critical angle?', '90°, so sin θ₂ = 1.', 'sin c = 1/n.'], mk: p => [[Math.asin(1 / p.n1), 'radians', 'That is in radians. Give the answer in degrees.']] }),
    phys({ id: 'ph-photon', strand: 'Optics', title: 'Photon energy', lv: [2, 4], grade: '12-college', focus: 'E = hc/λ', dim: 'E',
      gen: r => ({ lam: r.sig(380, 750, 3) * 1e-9 }), calc: p => C.h * C.c / p.lam, unit: 'eV',
      q: p => 'What is the energy of a photon of wavelength ' + f(p.lam * 1e9) + ' nm, in electronvolts? (h = 6.626 × 10⁻³⁴ J s, c = 2.998 × 10⁸ m/s, 1 eV = 1.602 × 10⁻¹⁹ J)',
      steps: (p, c) => [{ t: 'E = hc/λ = 6.626 × 10⁻³⁴ × 2.998 × 10⁸ / ' + f(p.lam) + ' m = ' + f(c.v) + ' J.' }, { t: 'Divide by 1.602 × 10⁻¹⁹ J/eV: E = ' + c.show(c.v) + '.' }],
      hints: () => ['Shorter wavelength means more energy.', 'E = hc / λ. Convert nm to m.', 'Then convert joules to electronvolts.'], mk: p => [[C.h * C.c / (p.lam * 1e9), 'nm', 'Convert nanometres to metres (× 10⁻⁹) first.'], [C.h * p.lam / C.c, 'flip', 'E = hc/λ.']] }),

    /* ---------------- thermodynamics ---------------- */
    phys({ id: 'ph-heat', strand: 'Thermodynamics', title: 'Specific heat capacity', lv: [1, 3], grade: '9-12', focus: 'Q = mcΔT', dim: 'E',
      gen: r => ({ m: r.sig(0.1, 5, 3), mat: r.int(0, 3), dT: r.sig(5, 80, 3) }), calc: p => p.m * [4186, 900, 385, 2100][p.mat] * p.dT, unit: 'kJ',
      q: p => 'How much energy heats ' + f(p.m) + ' kg of ' + ['water (c = 4186 J/(kg K))', 'aluminium (c = 900 J/(kg K))', 'copper (c = 385 J/(kg K))', 'ice (c = 2100 J/(kg K))'][p.mat] + ' by ' + f(p.dT) + ' K? Give the answer in kJ.',
      steps: (p, c) => [{ t: 'Q = mcΔT.' }, { t: 'Q = ' + f(p.m) + ' × ' + [4186, 900, 385, 2100][p.mat] + ' × ' + f(p.dT) + ' = ' + f(c.v) + ' J = ' + c.show(c.v) + '.' }],
      hints: () => ['Energy needed depends on mass, material and temperature rise.', 'Q = m c ΔT.', '1 kJ = 1000 J.'], mk: p => [[p.m * [4186, 900, 385, 2100][p.mat] * p.dT * 1000, 'kJ', 'Convert joules to kilojoules (÷ 1000).']] }),
    phys({ id: 'ph-latent', strand: 'Thermodynamics', title: 'Latent heat', lv: [1, 3], grade: '10-12', focus: 'Q = mL, no temperature change', dim: 'E',
      gen: r => ({ m: r.sig(0.05, 3, 3), boil: r.chance(0.5) ? 1 : 0 }), calc: p => p.m * (p.boil ? 2.26e6 : 3.34e5), unit: 'kJ',
      q: p => 'How much energy is needed to ' + (p.boil ? 'boil away ' + f(p.m) + ' kg of water at 100 °C (L = 2.26 × 10⁶ J/kg)' : 'melt ' + f(p.m) + ' kg of ice at 0 °C (L = 3.34 × 10⁵ J/kg)') + '? Give the answer in kJ.',
      steps: (p, c) => [{ t: 'During a change of state the temperature stays constant: Q = mL.' }, { t: 'Q = ' + f(p.m) + ' × ' + (p.boil ? '2.26 × 10⁶' : '3.34 × 10⁵') + ' = ' + c.show(c.v) + '.' }],
      hints: () => ['Is the temperature changing?', 'No: use Q = mL.', 'Multiply mass by the latent heat.'], mk: p => [[p.m * (p.boil ? 2.26e6 : 3.34e5) * 1000, 'kJ', 'Convert J to kJ (÷ 1000).']] }),
    phys({ id: 'ph-temp', strand: 'Thermodynamics', title: 'Temperature scales', lv: [0, 2], grade: '5-9', focus: 'K = °C + 273.15', dim: 'T',
      gen: (r, L) => ({ c: L.kid ? r.int(-10, 40) : r.int(-80, 300), to: L.kid ? 'F' : r.pick(['K', 'F']), sf: 3 }),
      calc: p => p.c + 273.15, unit: p => (p.to === 'K' ? 'K' : '°F'), opt: true,
      q: (p, L) => 'Convert ' + p.c + ' °C to ' + (p.to === 'K' ? 'kelvin' : 'degrees Fahrenheit') + (L.kid ? ' (°F = °C × 9/5 + 32).' : '.'),
      steps: (p, c) => p.to === 'K' ? [{ t: 'K = °C + 273.15.' }, { t: p.c + ' + 273.15 = ' + (p.c + 273.15).toFixed(2) + ' K.' }] : [{ t: '°F = °C × 9/5 + 32.' }, { t: p.c + ' × 9/5 + 32 = ' + SM.fmtNum(p.c * 9 / 5 + 32) + ' °F.' }],
      hints: p => ['Which formula links the two scales?', p.to === 'K' ? 'Add 273.15.' : 'Multiply by 9/5, then add 32.', p.to === 'K' ? 'The size of 1 K equals 1 °C.' : p.c + ' × 9/5 = ' + SM.fmtNum(p.c * 9 / 5) + '.'],
      mk: p => (p.to === 'K' ? [[p.c - 273.15, 'minus', 'Add 273.15 to go from °C to K.']] : [[((p.c + 32) * 9 / 5 + 459.67) * 5 / 9, 'order', 'Multiply by 9/5 first, then add 32.']]) }),
    phys({ id: 'ph-gas', strand: 'Thermodynamics', title: 'Ideal gas law', lv: [2, 4], grade: '11-college', focus: 'PV = nRT with T in kelvin', dim: 'Pa',
      gen: r => ({ n: r.sig(0.1, 5, 3), T: r.sig(250, 600, 3), V: r.sig(1, 50, 3) * 1e-3 }), calc: p => p.n * C.R * p.T / p.V, unit: 'kPa',
      q: p => f(p.n) + ' mol of an ideal gas is held at ' + f(p.T) + ' K in a ' + f(p.V * 1000) + ' L container. Using R = 8.314 J/(mol K), what is its pressure in kPa?',
      steps: (p, c) => [{ t: 'P = nRT/V, with V in m³ (1 L = 10⁻³ m³).' }, { t: 'P = ' + f(p.n) + ' × 8.314 × ' + f(p.T) + ' / ' + f(p.V) + ' = ' + f(c.v) + ' Pa = ' + c.show(c.v) + '.' }],
      hints: () => ['PV = nRT.', 'Use SI units: litres to cubic metres.', 'P = nRT / V.'], mk: p => [[p.n * C.R * p.T / (p.V * 1000), 'litres', 'Convert litres to m³ (× 10⁻³) before dividing.'], [p.n * C.R * (p.T - 273.15) / p.V, 'celsius', 'Temperature must be in kelvin.']] }),
    phys({ id: 'ph-carnot', strand: 'Thermodynamics', title: 'Carnot efficiency', lv: [3, 4], grade: 'college', focus: 'η = 1 - T_c/T_h in kelvin', approx: 1,
      gen: r => ({ th: r.int(200, 900), tc: r.int(0, 60) }), calc: p => (1 - (p.tc + 273.15) / (p.th + 273.15)) * 100, unit: '%',
      q: p => 'A heat engine runs between ' + p.th + ' °C and ' + p.tc + ' °C. What is its maximum (Carnot) efficiency, in percent to 1 decimal place?',
      steps: (p, c) => [{ t: 'Convert to kelvin: T_h = ' + (p.th + 273.15).toFixed(2) + ' K, T_c = ' + (p.tc + 273.15).toFixed(2) + ' K.' }, { t: 'η = 1 - T_c/T_h = ' + c.v.toFixed(1) + '%.' }],
      hints: () => ['The Carnot formula needs absolute temperatures.', 'Add 273.15 to each.', 'η = 1 - T_c / T_h.'], mk: p => [[(1 - p.tc / p.th) * 100, 'celsius', 'Use kelvin, not degrees Celsius.']],
      proof: 'For a reversible cycle the entropy taken from the hot reservoir equals that given to the cold one: Q_h/T_h = Q_c/T_c. Then η = 1 - Q_c/Q_h = 1 - T_c/T_h. Any real engine generates entropy and does worse.' }),

    /* ---------------- relativity and quantum ---------------- */
    phys({ id: 'ph-lorentz', strand: 'Modern physics', title: 'The Lorentz factor', lv: [3, 4], grade: 'college', focus: 'γ = 1/√(1 - v²/c²)', approx: 3,
      gen: r => ({ b: r.pick([0.30, 0.50, 0.60, 0.80, 0.90, 0.95, 0.99]) }), calc: p => 1 / Math.sqrt(1 - p.b * p.b), unit: '',
      q: p => 'What is the Lorentz factor γ for a speed of ' + p.b.toFixed(2) + 'c? Give 3 decimal places.',
      steps: (p, c) => [{ t: 'γ = 1/√(1 - β²) with β = ' + p.b.toFixed(2) + '.' }, { t: 'γ = 1/√(1 - ' + (p.b * p.b).toFixed(4) + ') = ' + c.v.toFixed(3) + '.' }],
      hints: () => ['β = v/c.', 'γ = 1 / √(1 - β²).', 'Square β first.'], mk: p => [[Math.sqrt(1 - p.b * p.b), 'inverse', 'That is 1/γ. Take the reciprocal.'], [1 / (1 - p.b * p.b), 'no-root', 'Take the square root of 1 - β².']],
      proof: 'From the invariance of c, a light clock moving at v has its light path lengthened by the factor 1/√(1 - v²/c²). The Lorentz transformation t\' = γ(t - vx/c²), x\' = γ(x - vt) is the unique linear map that keeps x² - c²t² invariant.' }),
    phys({ id: 'ph-dilation', strand: 'Modern physics', title: 'Time dilation', lv: [3, 4], grade: 'college', focus: 'moving clocks run slow: Δt = γΔt₀', dim: 't',
      gen: r => ({ b: r.pick([0.60, 0.80, 0.90, 0.95, 0.99]), t0: r.sig(1, 10, 3) * 1e-6 }), calc: p => p.t0 / Math.sqrt(1 - p.b * p.b), unit: 'μs',
      q: p => 'A particle has a lifetime of ' + f(p.t0 * 1e6) + ' μs at rest. What lifetime do we measure when it moves at ' + p.b.toFixed(2) + 'c?',
      steps: (p, c) => [{ t: 'Δt = γΔt₀ with γ = 1/√(1 - ' + p.b.toFixed(2) + '²) = ' + f(1 / Math.sqrt(1 - p.b * p.b), 4) + '.' }, { t: 'Δt = ' + c.show(c.v) + '.' }],
      hints: () => ['Moving clocks run slow, so the lifetime we see is longer.', 'Δt = γΔt₀.', 'Find γ first.'], mk: p => [[p.t0 * Math.sqrt(1 - p.b * p.b), 'divide', 'The lab lifetime is longer than the rest lifetime: multiply by γ.']] }),
    phys({ id: 'ph-contraction', strand: 'Modern physics', title: 'Length contraction', lv: [3, 4], grade: 'college', focus: 'L = L₀/γ', dim: 'L',
      gen: r => ({ b: r.pick([0.50, 0.60, 0.80, 0.90, 0.95]), L0: r.sig(10, 500, 3) }), calc: p => p.L0 * Math.sqrt(1 - p.b * p.b), unit: 'm',
      q: p => 'A spaceship is ' + f(p.L0) + ' m long at rest. How long is it measured to be as it passes at ' + p.b.toFixed(2) + 'c?',
      steps: (p, c) => [{ t: 'L = L₀√(1 - β²).' }, { t: 'L = ' + f(p.L0) + ' × √(1 - ' + p.b.toFixed(2) + '²) = ' + c.show(c.v) + '.' }],
      hints: () => ['Moving objects are shorter along their motion.', 'L = L₀ / γ.', 'γ = 1/√(1 - β²).'], mk: p => [[p.L0 / Math.sqrt(1 - p.b * p.b), 'times', 'Lengths contract: divide by γ.']] }),
    phys({ id: 'ph-rest-energy', strand: 'Modern physics', title: 'Mass-energy equivalence', lv: [3, 4], grade: 'college', focus: 'E = mc²', dim: 'E',
      gen: r => ({ m: r.sig(0.1, 50, 3) * 1e-3 }), calc: p => p.m * C.c * C.c, unit: 'J',
      q: p => 'How much energy is equivalent to a mass of ' + f(p.m * 1000) + ' g? (c = 2.998 × 10⁸ m/s)',
      steps: (p, c) => [{ t: 'E = mc², with m in kg.' }, { t: 'E = ' + f(p.m) + ' × (2.998 × 10⁸)² = ' + c.show(c.v) + '.' }], hints: () => ['E = mc².', 'Grams to kilograms first.', 'Square c.'], mk: p => [[p.m * C.c, 'no-square', 'Square the speed of light.'], [p.m * 1000 * C.c * C.c, 'grams', 'Convert grams to kilograms first.']] }),
    phys({ id: 'ph-debroglie', strand: 'Modern physics', title: 'de Broglie wavelength', lv: [3, 4], grade: 'college', focus: 'λ = h/p', dim: 'L',
      gen: r => ({ v: r.sig(1, 9, 3) * 1e6 }), calc: p => C.h / (C.me * p.v), unit: 'nm',
      q: p => 'What is the de Broglie wavelength of an electron moving at ' + f(p.v) + ' m/s (non-relativistic)? Use h = 6.626 × 10⁻³⁴ J s and mₑ = 9.109 × 10⁻³¹ kg.',
      steps: (p, c) => [{ t: 'λ = h/(mv).' }, { t: 'λ = 6.626 × 10⁻³⁴ / (9.109 × 10⁻³¹ × ' + f(p.v) + ') = ' + c.show(c.v) + '.' }], hints: () => ['Every particle has a wavelength.', 'λ = h / p and p = mv.', 'Divide h by the momentum.'], mk: p => [[C.me * p.v / C.h, 'flip', 'λ = h/p, not p/h.']] }),
    phys({ id: 'ph-hydrogen', strand: 'Modern physics', title: 'Hydrogen spectrum', lv: [3, 4], grade: 'college', focus: 'Eₙ = -13.6 eV / n²', dim: 'L',
      gen: r => { const n1 = r.int(1, 2); return { n1, n2: n1 + r.int(1, 4) }; }, calc: p => C.h * C.c / (C.Ry * C.eV * (1 / (p.n1 * p.n1) - 1 / (p.n2 * p.n2))), unit: 'nm',
      q: p => 'An electron in hydrogen drops from n = ' + p.n2 + ' to n = ' + p.n1 + '. Using Eₙ = -13.606 eV/n², hc = 1239.84 eV nm, what is the wavelength of the emitted photon?',
      steps: (p, c) => [{ t: 'ΔE = 13.606 (1/' + p.n1 + '² - 1/' + p.n2 + '²) eV = ' + f(C.Ry * (1 / (p.n1 * p.n1) - 1 / (p.n2 * p.n2)), 4) + ' eV.' }, { t: 'λ = hc/ΔE = ' + c.show(c.v) + '.' }],
      hints: () => ['Find the energy difference between the levels.', 'ΔE = 13.6 eV × (1/n₁² - 1/n₂²).', 'λ = hc / ΔE.'], mk: p => [[C.h * C.c / (C.Ry * C.eV * (1 / p.n1 - 1 / p.n2)), 'no-square', 'The levels go as 1/n², not 1/n.']],
      proof: 'In the Bohr model, quantising angular momentum (L = nħ) with the Coulomb force gives Eₙ = -mₑe⁴/(8ε₀²h²n²) = -R_∞hc/n². The Schrödinger equation for the Coulomb potential gives the same levels.' }),
    phys({ id: 'ph-box', strand: 'Modern physics', title: 'Particle in a box', lv: [3, 4], grade: 'college', focus: 'Eₙ = n²h²/8mL²', dim: 'E',
      gen: r => ({ n: r.int(1, 4), L: r.sig(0.1, 2, 3) * 1e-9 }), calc: p => p.n * p.n * C.h * C.h / (8 * C.me * p.L * p.L), unit: 'eV',
      q: p => 'An electron is confined to a 1-D box of width ' + f(p.L * 1e9) + ' nm. What is the energy of level n = ' + p.n + ', in eV? (h = 6.626 × 10⁻³⁴ J s, mₑ = 9.109 × 10⁻³¹ kg)',
      steps: (p, c) => [{ t: 'Eₙ = n²h²/(8mL²).' }, { t: 'E = ' + p.n * p.n + ' × (6.626 × 10⁻³⁴)² / (8 × 9.109 × 10⁻³¹ × (' + f(p.L) + ')²) = ' + c.show(c.v) + '.' }],
      hints: () => ['Standing waves fit in the box: λ = 2L/n.', 'p = h/λ and E = p²/2m.', 'Eₙ = n²h²/(8mL²).'], mk: p => [[p.n * C.h * C.h / (8 * C.me * p.L * p.L), 'n-not-sq', 'Energy grows as n².']],
      proof: 'With ψ = 0 at both walls, ψₙ = √(2/L) sin(nπx/L). Then -ħ²/2m ψ\'\' = Eψ gives Eₙ = ħ²π²n²/(2mL²) = n²h²/(8mL²).' }),
    phys({ id: 'ph-uncertainty', strand: 'Modern physics', title: 'The uncertainty principle', lv: [3, 4], grade: 'college', focus: 'Δx Δp ≥ ħ/2', dim: 'v',
      gen: r => ({ dx: r.sig(0.05, 5, 3) * 1e-9 }), calc: p => C.hbar / (2 * p.dx * C.me), unit: 'km/s',
      q: p => 'An electron is located within Δx = ' + f(p.dx * 1e9) + ' nm. What is the minimum uncertainty in its speed? (ħ = 1.055 × 10⁻³⁴ J s, mₑ = 9.109 × 10⁻³¹ kg)',
      steps: (p, c) => [{ t: 'Δp ≥ ħ/(2Δx), and Δv = Δp/m.' }, { t: 'Δv = 1.055 × 10⁻³⁴ / (2 × ' + f(p.dx) + ' × 9.109 × 10⁻³¹) = ' + c.show(c.v) + '.' }],
      hints: () => ['Narrowing position widens momentum.', 'Δp_min = ħ / (2Δx).', 'Divide by the electron mass.'], mk: p => [[C.h / (2 * p.dx * C.me), 'h-not-hbar', 'Use ħ = h/2π, not h.'], [C.hbar / (p.dx * C.me), 'no-2', 'The bound is ħ/2.']] }),
  ]);
})();
